using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
namespace GearLab {
 public sealed class ShaftLoadResult {
  public double Diameter,Span,Overhang,LoadZ,Reaction1,Reaction2,Reaction1X,Reaction1Y,Reaction2X,Reaction2Y,BendingMoment,BendingStress,AxialStress,TorsionStress,EquivalentStress;public double? Deflection,Slope,YieldMargin,Axial1,Axial2;public string Note;
 }
 public sealed class FailureEstimate {public string Mode,Part,Formula,Note;public double? LimitTorque,Margin;public bool Applicable=true;}
 public sealed class TrainStrengthResult {public ShaftLoadResult Shaft;public List<FailureEstimate> Modes=new List<FailureEstimate>();public List<string> Notes=new List<string>();public double? LimitTorque,StructuralLimit,ClutchTorque,SpringForce;public string WeakestPart;public double WorkingTorque;public bool ReadyForManufacture{get{return false;}}}
 public static class TrainStrength {
  static void Number(double v,double lo,double hi,string name){if(!MechanismCad.Finite(v)||v<lo||v>hi)throw new Exception(name+": недопустимое число.");}
  public static void Validate(TransmissionTrain t){if(t.Materials!=null)MaterialLibrary.Resolve(t);var f=t.OutputLoad;if(f!=null){foreach(double v in new[]{f.RadialForce,f.AxialForce,f.ForceOffset})Number(v,0,1000000,"Нагрузка на вал");Number(f.ForceAngle,-360,360,"Направление силы");if(f.OutputTorque.HasValue)Number(f.OutputTorque.Value,0,1000000,"Рабочий момент");if(!new[]{"Unknown","First","Second"}.Contains(f.AxialSupport))throw new Exception("Выберите фиксирующую осевую опору либо «не определено».");}var c=t.Overload;if(c!=null){if(!string.IsNullOrWhiteSpace(c.FrictionMaterial)&&!MaterialLibrary.Resolve(t).Any(m=>m.Name==c.FrictionMaterial))throw new Exception("Неизвестный материал трения: "+c.FrictionMaterial);Number(c.MeanRadius,.1,100,"Радиус трения");Number(c.SpringForce,0,100000,"Усилие пружины");if(c.Surfaces<1||c.Surfaces>20)throw new Exception("Число поверхностей трения 1–20.");if(c.Friction.HasValue)Number(c.Friction.Value,.0001,2,"Коэффициент трения");if(c.TargetTorque.HasValue)Number(c.TargetTorque.Value,0,1000000,"Момент срабатывания");if(c.ClutchEnabled&&!CompoundReducer.Enabled(t))throw new Exception("Для муфты включите общий корпус.");}}
  public static ShaftLoadResult Beam(double diameter,double first,double second,double loadZ,double radial,double axial,double torque,double angle,double? elastic,double? yield,string axialSupport){foreach(double v in new[]{diameter,first,second,loadZ,radial,axial,torque,angle})if(!MechanismCad.Finite(v))throw new Exception("Нагрузка: конечные числа обязательны.");if(diameter<=0||second<=first||loadZ<second||radial<0||axial<0||torque<0)throw new Exception("Нагрузка: нужна консоль за второй опорой и положительный диаметр.");if(elastic.HasValue&&(!MechanismCad.Finite(elastic.Value)||elastic.Value<=0)||yield.HasValue&&(!MechanismCad.Finite(yield.Value)||yield.Value<0))throw new Exception("Материал вала: E должен быть положительным, предел — неотрицательным; неизвестное значение оставьте пустым.");double l=second-first,a=loadZ-second,i=Math.PI*Math.Pow(diameter,4)/64;var r=new ShaftLoadResult{Diameter=diameter,Span=l,Overhang=a,LoadZ=loadZ,Reaction1=-radial*a/l,Reaction2=radial*(l+a)/l,BendingMoment=radial*a};double c=Math.Cos(angle*Math.PI/180),s=Math.Sin(angle*Math.PI/180);r.Reaction1X=r.Reaction1*c;r.Reaction1Y=r.Reaction1*s;r.Reaction2X=r.Reaction2*c;r.Reaction2Y=r.Reaction2*s;r.BendingStress=32*r.BendingMoment/(Math.PI*Math.Pow(diameter,3));r.AxialStress=4*axial/(Math.PI*diameter*diameter);r.TorsionStress=16*torque*1000/(Math.PI*Math.Pow(diameter,3));r.EquivalentStress=Math.Sqrt(Math.Pow(r.BendingStress+r.AxialStress,2)+4*r.TorsionStress*r.TorsionStress);if(elastic.HasValue&&elastic>0){r.Deflection=radial*a*a*(l+a)/(3*elastic.Value*i);r.Slope=radial*(a*l/3+a*a/2)/(elastic.Value*i);}if(yield.HasValue)r.YieldMargin=r.EquivalentStress==0?(double?)null:yield.Value/r.EquivalentStress;if(axial==0)r.Axial1=r.Axial2=0;else if(axialSupport=="First"){r.Axial1=axial;r.Axial2=0;}else if(axialSupport=="Second"){r.Axial1=0;r.Axial2=axial;}r.Note="Две шарнирные опоры и консоль, круглый сплошной вал постоянного d, линейная балка Эйлера–Бернулли: R1=−Fa/L, R2=F(L+a)/L; M=Fa; σb=32M/(πd³), τ=16T/(πd³), σa=4Fa/(πd²); Tresca: σeq=√((σb+σa)²+4τ²). δ=Fa²(L+a)/(3EI), θ=F(aL/3+a²/2)/(EI), I=πd⁴/64. Единицы N, mm, MPa, T переведён из Nm в Nmm. Без концентраций, пластичности и ползучести.";return r;}
  static double Factor(TrainMaterial m){return m==null?1:m.Kind=="FDM"?m.LayerFactor:1;}
  static FailureEstimate Unknown(string mode,string part,string formula,string why){return new FailureEstimate{Mode=mode,Part=part,Formula=formula,Note="Не определено: "+why};}
  static void Add(TrainStrengthResult r,string mode,string part,double? limit,string formula,string note){if(limit.HasValue&&(!MechanismCad.Finite(limit.Value)||limit<0))throw new Exception("Некорректный предел: "+mode);r.Modes.Add(new FailureEstimate{Mode=mode,Part=part,LimitTorque=limit,Formula=formula,Note=note,Margin=limit.HasValue&&r.WorkingTorque>0?limit.Value/r.WorkingTorque:(double?)null});}
  public static TrainStrengthResult Calculate(TransmissionTrain t,TrainSolution s){var r=new TrainStrengthResult();var chain=CompoundReducer.Ordered(t);var last=s.States[chain.Last().Id];var load=t.OutputLoad??new TrainOutputLoad();r.WorkingTorque=load.OutputTorque??last.OutputTorque;var output=s.Scene.Model.Parts.First(q=>q.Id.EndsWith("_SH_OUTPUT_CARRIER")||q.Id=="SH_CLUTCH_OUTPUT");if(t.Overload!=null&&t.Overload.ClutchEnabled)output=s.Scene.Model.Parts.First(q=>q.Id=="SH_CLUTCH_OUTPUT");var material=MaterialLibrary.For(t,output);double? yield=material==null||!material.Yield.HasValue?(double?)null:material.Yield.Value*Factor(material);r.Shaft=Beam(s.Compound.OutputDiameter,s.Compound.Support1,s.Compound.Support2,s.Compound.OutputPlane+load.ForceOffset,load.RadialForce,load.AxialForce,r.WorkingTorque,load.ForceAngle,material==null?null:material.Elastic,yield,load.AxialSupport);r.Notes.Add(r.Shaft.Note);if(r.Shaft.Deflection.HasValue&&r.Shaft.Deflection>r.Shaft.Span*.05)r.Notes.Add("Прогиб превышает 5% пролёта: допущение малых прогибов неприменимо, нужна нелинейная проверка.");r.Notes.Add("Осевая нагрузка распределяется только при явном выборе фиксирующей опоры. Без него реакции по оси не определены. L10 не рассчитывается: нет каталожной C и режима работы.");
   foreach(var node in chain){var st=s.States[node.Id];var p=st.Result.P;double downstream=1;bool found=false;foreach(var n in chain){if(n.Id==node.Id)found=true;if(found)downstream*=s.States[n.Id].Result.Actual*s.States[n.Id].Efficiency;}
    foreach(var gear in s.Scene.Model.Parts.Where(q=>q.Id.StartsWith(node.Id+"_")&&q.Role=="gear")){var m=MaterialLibrary.For(t,gear);int teeth=gear.Id.Contains("_SUN")?st.Result.Z1:gear.Id.Contains("_PLANET_")?st.Result.Zp:0;double? strength=m==null?null:m.Yield??m.Tensile;if(p.Kind==3&&teeth>=17&&Math.Abs(p.PressureAngle-20)<1e-8&&strength.HasValue){double y=Math.PI*(.154-.912/teeth),sigmaPerOutput=2000/(p.Module*st.Result.Z1*downstream)*p.ServiceFactor/(p.Thickness*p.Module*y);double limit=strength.Value/sigmaPerOutput;Add(r,"Изгиб зуба (Lewis)",gear.Id,limit,"σ=FtK/(bmY); Y=π(0,154−0,912/z)","Один сателлит принимает всю нагрузку (консервативное допущение); без галтели и усталости. Предел по заданному материалу, не ISO/AGMA.");if(m.Kind=="FDM")Add(r,"Поперёк слоёв",gear.Id,limit*m.LayerFactor,"Tслои=Tбаза·LayerFactor","LayerFactor задан пользователем; ориентация слоёв в расчёте не оптимизируется.");}else r.Modes.Add(Unknown("Изгиб зуба",gear.Id,"σ=FtK/(bmY)","для этой геометрии нет применимой формы Lewis либо не задана прочность материала"));}
    r.Modes.Add(Unknown("Срез зуба",node.Id,"τ=Ft/(b·s)","толщина основания зуба s в опасном сечении не выделена из профиля"));if(p.Kind==0)r.Modes.Add(Unknown("Смятие зацепа / ролика",node.Id,"p=F/(d·b)","не заданы действительное распределение нагрузки между зацепами и допускаемое контактное давление; это не расчёт Герца"));
   }
   foreach(var joint in s.Scene.Model.Parts.Where(q=>q.Id.StartsWith("SH_JOINT_"))){var m=MaterialLibrary.For(t,joint);int index=int.Parse(joint.Id.Substring(9))-1;var st=s.States[chain[index].Id];double d=st.Result.P.OutputShaft,ratioToFinal=1;for(int j=index+1;j<chain.Count;j++)ratioToFinal*=s.States[chain[j].Id].Result.Actual*s.States[chain[j].Id].Efficiency;if(t.SharedHousing.Joint=="CommonShaft"&&m!=null&&(m.Shear.HasValue||m.Yield.HasValue)){double shear=m.Shear??m.Yield.Value/2;Add(r,"Кручение соединения",joint.Id,shear*Factor(m)*Math.PI*d*d*d/16/1000*ratioToFinal,"τ=16T/(πd³); при заданной текучести τy=σy/2 (Tresca)","Круглая шейка общего вала; без концентраций у ступеней и усталости.");}else r.Modes.Add(Unknown("Срез соединения",joint.Id,"τ=T/Wt",t.SharedHousing.Joint=="CommonShaft"?"не задан предел среза/текучести":"не определён коэффициент кручения нестандартного D-/шлицевого профиля; формула 2T/(d·l·k) требует размерной геометрии k"));}
   var stud=s.Scene.Model.Parts.First(q=>q.Id=="SH_STUD_1");var sm=MaterialLibrary.For(t,stud);if(sm!=null&&(sm.Shear.HasValue||sm.Yield.HasValue)){var c=stud.Sections[0].Outer;double radius=Math.Sqrt(c.X*c.X+c.Y*c.Y),area=Math.PI*t.SharedHousing.BoltDiameter*t.SharedHousing.BoltDiameter/4,reaction=Math.Abs(1/Math.Abs(s.TotalRatio*s.TotalEfficiency)-Math.Sign(last.OutputGain));Add(r,"Срез шпилек",stud.Id,(sm.Shear??sm.Yield.Value/2)*Factor(sm)*t.SharedHousing.Bolts*area*radius/(1000*reaction),"τ=Tкорп/(n·R·A); Tкорп=|Tвх−sign(g)Tвых|","Равномерная касательная нагрузка группы шпилек, без трения стыков и преднатяга; локальное смятие отверстий не оценено.");}else r.Modes.Add(Unknown("Срез шпилек",stud.Id,"τ=F/(n·A)","не задан предел среза/текучести шпильки"));r.Modes.Add(new FailureEstimate{Mode="Вырыв резьбы в пластике",Part="SH_MODULE_*",Formula="τ=F/(πdh)",Applicable=false,Note="Не применяется: корпус стянут сквозными шпильками с металлическими гайками; пластиковой резьбы нет. Смятие под гайками не оценено."});
   if(yield.HasValue){double normal=r.Shaft.BendingStress+r.Shaft.AxialStress,limit=normal>=yield.Value?0:Math.Sqrt(yield.Value*yield.Value-normal*normal)*Math.PI*Math.Pow(r.Shaft.Diameter,3)/32/1000;Add(r,"Текучесть выходного вала",output.Id,limit,"σeq=√((σb+σa)²+4τ²) ≤ σy·LayerFactor","Радиальная/осевая нагрузки постоянны при увеличении момента; круглое сплошное сечение.");}else r.Modes.Add(Unknown("Текучесть выходного вала",output.Id,"Tresca","не задан предел текучести материала вала"));
   var known=r.Modes.Where(m=>m.LimitTorque.HasValue).OrderBy(m=>m.LimitTorque).ToList();if(known.Count>0){r.LimitTorque=known[0].LimitTorque;r.WeakestPart=known[0].Part;}r.Notes.Add("Предельный момент определён по проверенным пунктам; остальные не оценены. Это минимум частных предварительных оценок, а не гарантированная грузоподъёмность конструкции.");
   r.StructuralLimit=r.LimitTorque;var clutch=t.Overload;if(clutch!=null&&clutch.ClutchEnabled){double? friction=clutch.Friction??(string.IsNullOrWhiteSpace(clutch.FrictionMaterial)?(double?)null:MaterialLibrary.Resolve(t).First(m=>m.Name==clutch.FrictionMaterial).Friction);if(friction.HasValue&&friction.Value<=0)throw new Exception("Для расчёта муфты задайте положительный коэффициент трения пары; при μ=0 передача момента отсутствует.");if(friction.HasValue){r.SpringForce=clutch.TargetTorque.HasValue?clutch.TargetTorque.Value/(friction.Value*clutch.MeanRadius/1000*clutch.Surfaces):clutch.SpringForce;r.ClutchTorque=friction.Value*r.SpringForce.Value*clutch.MeanRadius/1000*clutch.Surfaces;Add(r,"Проскальзывание муфты","SH_CLUTCH_OUTPUT",r.ClutchTorque,"T=μ·F·R·z; F=T/(μRz)","F="+Engine.F(r.SpringForce.Value)+" Н; R="+Engine.F(clutch.MeanRadius)+" мм; μ="+Engine.F(friction.Value)+"; z="+clutch.Surfaces+". Жёсткость, ход пружины, износ и динамика не рассчитаны.");if(r.LimitTorque.HasValue&&r.ClutchTorque>r.LimitTorque)r.Notes.Add("Муфта настроена выше оценённого предела слабого звена: она не обеспечивает его защиту.");if(!r.LimitTorque.HasValue)r.Notes.Add("Предел деталей неизвестен: защиту муфтой подтвердить нельзя.");}else r.Modes.Add(Unknown("Проскальзывание муфты","SH_CLUTCH_OUTPUT","T=μFRz","не задан коэффициент трения пары"));}var minimum=r.Modes.Where(m=>m.LimitTorque.HasValue).OrderBy(m=>m.LimitTorque).FirstOrDefault();if(minimum!=null){r.LimitTorque=minimum.LimitTorque;r.WeakestPart=minimum.Part;}return r;
  }
  public static string Report(TrainStrengthResult r,bool csv){var text=new StringBuilder(csv?"Способ;Деталь;Предел Нм;Запас;Формула;Примечание\r\n":"ПРЕДВАРИТЕЛЬНАЯ ОЦЕНКА. ReadyForManufacture=false\r\n");foreach(var m in r.Modes){var values=new[]{m.Mode,m.Part,m.LimitTorque.HasValue?CadNumbers.F(m.LimitTorque.Value):"не определено",m.Margin.HasValue?CadNumbers.F(m.Margin.Value):"не определено",m.Formula,m.Note};text.AppendLine(csv?string.Join(";",values.Select(v=>"\""+(v??"").Replace("\"","\"\"")+"\"")):string.Join(" | ",values));}if(csv)text.AppendLine("\"STATUS\";\"ReadyForManufacture=false; предел только по оценённым пунктам\"");else text.AppendLine(string.Join("\r\n",r.Notes));return text.ToString();}
 }
}
